import { InvariantViolationError } from './errors.js';
import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

/**
 * Ensures the git worktree is clean before starting any self-healing mutation.
 */
export function assertCleanWorktree(allowedPathsPrefix = 'demo'): void {
  try {
    const status = execSync('git status --porcelain', { encoding: 'utf-8' }).trim();
    if (status.length > 0) {
      const dirtyFiles = status.split('\n').map(line => line.trim().substring(3));
      const nonAllowed = dirtyFiles.filter(f => !f.startsWith(allowedPathsPrefix) && !f.startsWith('scratch'));
      if (nonAllowed.length > 0) {
        throw new InvariantViolationError(
          `Worktree has uncommitted changes outside sandbox: ${nonAllowed.join(', ')}`
        );
      }
    }
  } catch (err: any) {
    if (err instanceof InvariantViolationError) {
      throw err;
    }
    // If git error, fail closed
    throw new InvariantViolationError(`Unable to verify worktree cleanliness: ${err.message}`);
  }
}

/**
 * Validates that the target file exists, is inside the allowed workspace/demo boundary,
 * and contains valid contents.
 */
export function assertValidTargetFile(filePath: string): void {
  if (!filePath || filePath.trim() === '') {
    throw new InvariantViolationError('Target file path cannot be empty.');
  }

  const resolved = path.resolve(filePath);
  if (!fs.existsSync(resolved)) {
    throw new InvariantViolationError(`Target file does not exist on disk: ${filePath}`);
  }

  // Bound to demo/ or workspace
  const workspaceRoot = process.cwd();
  if (!resolved.startsWith(workspaceRoot)) {
    throw new InvariantViolationError(`Target file is outside the workspace root: ${filePath}`);
  }
}

/**
 * Ensures measured values are genuine numbers and not placeholder mocks.
 */
export function assertMeasuredMetric(metricName: string, value: number): void {
  if (value === undefined || value === null || isNaN(value) || value < 0) {
    throw new InvariantViolationError(`Metric '${metricName}' was not measured accurately. Got: ${value}`);
  }
}

import { exec } from 'child_process';
import { promisify } from 'util';
import { assertCleanWorktree } from '../core/invariants.js';

const execAsync = promisify(exec);

export class GitSandbox {
  static async isPristine(allowedPrefix = 'demo'): Promise<boolean> {
    try {
      assertCleanWorktree(allowedPrefix);
      return true;
    } catch {
      return false;
    }
  }

  static async getModifiedFiles(): Promise<string[]> {
    try {
      const { stdout } = await execAsync('git status --porcelain');
      if (!stdout.trim()) return [];
      return stdout
        .trim()
        .split('\n')
        .map((line) => line.trim().substring(3));
    } catch {
      return [];
    }
  }

  static async getDiff(): Promise<string> {
    try {
      const { stdout } = await execAsync('git diff');
      return stdout;
    } catch {
      return '';
    }
  }
}

import { exec } from 'child_process';
import { promisify } from 'util';
import { CheckpointFailed } from '../core/errors.js';
import { CheckpointInfo } from '../core/types.js';

const execAsync = promisify(exec);

export class CheckpointManager {
  private checkpoints: Map<string, CheckpointInfo> = new Map();

  async save(tag: string): Promise<string> {
    const id = `cp_${Date.now()}_${tag}`;
    let type: 'entire-native' | 'git-safety-net' = 'entire-native';

    try {
      // Attempt Entire native checkpoint if available
      await execAsync(`entire checkpoint save "${id}"`);
      console.log(`[Entire] Created native checkpoint: ${id}`);
    } catch {
      // Honest label: git safety net (behavioral parity, no session context)
      type = 'git-safety-net';
      console.log(`[Entire] Using git safety net branch: ${id} (behavioral parity, no session context)`);
      try {
        await execAsync(`git branch -f ${id} HEAD`);
      } catch (gitErr: any) {
        throw new CheckpointFailed(`Git checkpoint creation failed: ${gitErr.message}`);
      }
    }

    const info: CheckpointInfo = {
      id,
      tag,
      createdAt: Date.now(),
      type
    };
    this.checkpoints.set(id, info);

    return id;
  }

  async restore(id: string): Promise<number> {
    const start = Date.now();
    try {
      await execAsync(`entire checkpoint restore "${id}"`);
      console.log(`[Entire] Restored from native checkpoint: ${id}`);
    } catch {
      try {
        console.log(`[Entire] Rolling back via git safety net to: ${id}`);
        await execAsync(`git reset --hard ${id}`);
        // CRITICAL: Scope clean strictly to demo/ to avoid wiping runs/posts/ or evidence files!
        await execAsync(`git clean -fd -- demo/`);
      } catch (err: any) {
        throw new CheckpointFailed(`Rollback failed: ${err.message}`);
      }
    }
    const duration = Date.now() - start;
    console.log(`[Entire] Rollback complete in ${duration}ms`);
    return duration;
  }

  async isTreePristine(): Promise<boolean> {
    try {
      const { stdout } = await execAsync(`git status --porcelain`);
      return stdout.trim().length === 0;
    } catch {
      return false;
    }
  }

  getCheckpointInfo(id: string): CheckpointInfo | undefined {
    return this.checkpoints.get(id);
  }
}

import { exec } from 'child_process';
import { promisify } from 'util';
import * as fs from 'fs';
import * as path from 'path';
import { AstQueryFailed } from '../core/errors.js';
import { AstCaller, BlastRadiusReport } from '../core/types.js';

const execAsync = promisify(exec);

export async function resolveAstBlastRadius(
  filePath: string,
  line: number
): Promise<BlastRadiusReport> {
  const normPath = filePath.replace(/\\/g, '/');
  const targetSymbol = `${normPath}:${line}`;

  try {
    // Run entire graph impact using the official CLI format discovered in Spike 1
    const { stdout, stderr } = await execAsync(
      `entire graph impact --repo . --symbol "${targetSymbol}" --format json`
    );

    const parsed = JSON.parse(stdout);

    if (parsed.focus && parsed.focus.name) {
      const targetFunction = parsed.focus.name;
      const callers: AstCaller[] = [];

      if (parsed.callers && Array.isArray(parsed.callers.entries)) {
        for (const entry of parsed.callers.entries) {
          const endpoint = entry.endpoint;
          const callSite = entry.call_site;
          if (endpoint) {
            callers.push({
              filePath: (callSite?.file_path || endpoint.file_path || '').replace(/\\/g, '/'),
              functionName: endpoint.name || 'anonymous',
              lineNumber: callSite?.line || endpoint.start_line || 0,
              relation: entry.relation || 'CALLS'
            });
          }
        }
      }

      const callees: string[] = [];
      if (parsed.callees && Array.isArray(parsed.callees.entries)) {
        for (const entry of parsed.callees.entries) {
          if (entry.endpoint?.name) {
            callees.push(entry.endpoint.name);
          }
        }
      }

      console.log(
        `[Entire] Resolved symbol '${targetFunction}' with ${callers.length} callers via entire-graph`
      );

      return {
        targetFunction,
        filePath: normPath,
        lineNumber: line,
        callers,
        callees,
        resolvedVia: 'entire-graph'
      };
    }

    throw new Error('No focus symbol found in entire graph output');
  } catch (err: any) {
    console.warn(
      `[Entire] 'entire graph impact' failed or returned unexpected payload: ${err.message}. Activating regex AST parser fallback...`
    );
    return regexAstFallback(normPath, line);
  }
}

/**
 * Deterministic regex-based AST fallback parser:
 * Reads the target source file, scans upward from crash line to locate enclosing function,
 * and searches calling files in demo/service for callers.
 */
export function regexAstFallback(
  filePath: string,
  line: number
): BlastRadiusReport {
  try {
    const fullPath = path.resolve(filePath);
    if (!fs.existsSync(fullPath)) {
      throw new AstQueryFailed(`Target file ${filePath} does not exist`);
    }

    const content = fs.readFileSync(fullPath, 'utf-8');
    const lines = content.split('\n');

    // Scan upward from crash line to find enclosing function / handler
    let targetFunction = 'unknownFunction';
    const scanStart = Math.min(line - 1, lines.length - 1);
    for (let i = scanStart; i >= 0; i--) {
      const l = lines[i];
      const match =
        l.match(/(?:export\s+)?(?:async\s+)?function\s+([a-zA-Z0-9_$]+)/) ||
        l.match(/(?:export\s+)?(?:const|let|var)\s+([a-zA-Z0-9_$]+)\s*=\s*(?:async\s*)?\(/) ||
        l.match(/([a-zA-Z0-9_$]+)\s*\([^)]*\)\s*\{/);
      if (match) {
        targetFunction = match[1] || match[2] || match[3] || targetFunction;
        break;
      }
    }

    const callers: AstCaller[] = [];
    const searchDirs = [path.resolve('demo/service'), path.resolve('src')];

    for (const searchDir of searchDirs) {
      if (fs.existsSync(searchDir) && targetFunction !== 'unknownFunction') {
        const files = getAllFiles(searchDir);
        for (const f of files) {
          if ((f.endsWith('.ts') || f.endsWith('.js')) && !f.endsWith('.test.ts')) {
            const relPath = path.relative(process.cwd(), f).replace(/\\/g, '/');
            const fileLines = fs.readFileSync(f, 'utf-8').split('\n');
            fileLines.forEach((fileLine, idx) => {
              // Exclude the definition line itself
              if (
                fileLine.includes(targetFunction) &&
                !(relPath === filePath && idx + 1 <= line && idx + 1 >= line - 10)
              ) {
                callers.push({
                  filePath: relPath,
                  functionName: fileLine.trim().slice(0, 40),
                  lineNumber: idx + 1,
                  relation: 'CALLS'
                });
              }
            });
          }
        }
      }
    }

    console.log(
      `[Regex-AST] Isolated function: "${targetFunction}" with ${callers.length} callers`
    );

    return {
      targetFunction,
      filePath,
      lineNumber: line,
      callers,
      callees: [],
      resolvedVia: 'regex-fallback'
    };
  } catch (err: any) {
    throw new AstQueryFailed(`Regex AST fallback failed: ${err.message}`);
  }
}

function getAllFiles(dirPath: string, arrayOfFiles: string[] = []): string[] {
  const files = fs.readdirSync(dirPath);

  files.forEach((file) => {
    const fullPath = path.join(dirPath, file);
    if (fs.statSync(fullPath).isDirectory()) {
      arrayOfFiles = getAllFiles(fullPath, arrayOfFiles);
    } else {
      arrayOfFiles.push(fullPath);
    }
  });

  return arrayOfFiles;
}

import { resolveAstBlastRadius } from './entire_graph.js';
import { BlastRadiusReport, AstCaller } from '../core/types.js';
import * as fs from 'fs';
import * as path from 'path';

export interface ComprehensiveImpact {
  report: BlastRadiusReport;
  impactedRoutes: string[];
  affectedTests: string[];
  summary: string;
}

export async function analyzeBlastRadius(
  filePath: string,
  lineNumber: number
): Promise<ComprehensiveImpact> {
  const report = await resolveAstBlastRadius(filePath, lineNumber);

  const impactedRoutes: string[] = [];
  const affectedTests: string[] = [];

  // Check callers for route registrations or API calls
  for (const caller of report.callers) {
    if (caller.filePath.includes('routes') || caller.filePath.includes('server')) {
      impactedRoutes.push(`${caller.filePath}:${caller.lineNumber} (${caller.functionName})`);
    }
  }

  // Scan tests directory for mentions of the target function
  const testDir = path.resolve('demo/tests');
  if (fs.existsSync(testDir)) {
    const testFiles = fs.readdirSync(testDir);
    for (const file of testFiles) {
      if (file.endsWith('.test.ts') || file.endsWith('.spec.ts')) {
        const fullPath = path.join(testDir, file);
        const content = fs.readFileSync(fullPath, 'utf-8');
        if (content.includes(report.targetFunction)) {
          affectedTests.push(`demo/tests/${file}`);
        }
      }
    }
  }

  const summary = `Function '${report.targetFunction}' in '${report.filePath}' (line ${report.lineNumber}) has ${report.callers.length} downstream caller(s), affecting ${impactedRoutes.length} route(s) and ${affectedTests.length} test suite(s).`;

  return {
    report,
    impactedRoutes,
    affectedTests,
    summary
  };
}

import { FailureSpan } from '../core/types.js';

export interface ParsedStackTrace {
  filePath: string;
  lineNumber: number;
  columnNumber: number;
  functionName?: string;
}

export class TraceInterceptor {
  /**
   * Parse an error or stack trace string to identify the origin file, line, and function.
   */
  static parseStackTrace(stack: string): ParsedStackTrace | null {
    if (!stack) return null;

    const lines = stack.split('\n');
    for (const line of lines) {
      // Common V8 stack trace format: "    at functionName (filepath:line:col)" or "    at filepath:line:col"
      const matchWithFunc = line.match(/^\s*at\s+([a-zA-Z0-9_$.<>]+)\s+\((.*?):(\d+):(\d+)\)/);
      if (matchWithFunc) {
        const filePath = matchWithFunc[2].replace(/\\/g, '/');
        // Ignore internal node modules or node_modules
        if (!filePath.includes('node_modules') && !filePath.startsWith('node:')) {
          return {
            functionName: matchWithFunc[1],
            filePath,
            lineNumber: parseInt(matchWithFunc[3], 10),
            columnNumber: parseInt(matchWithFunc[4], 10),
          };
        }
      }

      const matchWithoutFunc = line.match(/^\s*at\s+(.*?):(\d+):(\d+)/);
      if (matchWithoutFunc) {
        const filePath = matchWithoutFunc[1].replace(/\\/g, '/');
        if (!filePath.includes('node_modules') && !filePath.startsWith('node:')) {
          return {
            filePath,
            lineNumber: parseInt(matchWithoutFunc[2], 10),
            columnNumber: parseInt(matchWithoutFunc[3], 10),
          };
        }
      }
    }

    return null;
  }

  /**
   * Enrich raw span data with parsed stack trace details.
   */
  static extractFailureContext(span: FailureSpan): FailureSpan {
    if (!span.errorStack) {
      return span;
    }

    const parsed = this.parseStackTrace(span.errorStack);
    if (parsed) {
      return {
        ...span,
        filePath: parsed.filePath,
        lineNumber: parsed.lineNumber,
      };
    }

    return span;
  }
}

import { TraceFetchFailed } from '../core/errors.js';
import { FailureSpan, ComparativeEvalResult } from '../core/types.js';
import { TraceInterceptor } from './trace_interceptor.js';
import * as fs from 'fs';
import * as path from 'path';

export class TelemetryService {
  private client: any = null;
  private seenTraceIds = new Set<string>();
  private lastPolledTimestamp = Date.now();
  private traceUrlTemplate: string;
  private apiKey?: string;
  private localTelemetryQueueFile: string;

  constructor(apiKey?: string, traceUrlTemplate?: string) {
    this.apiKey = apiKey || process.env.NEATLOGS_API_KEY;
    this.traceUrlTemplate = traceUrlTemplate || process.env.TRACE_URL_TEMPLATE || 'https://app.neatlogs.com/traces/${id}';
    this.localTelemetryQueueFile = path.resolve('.neatlogs_local_spans.json');
  }

  async init(): Promise<void> {
    if (this.apiKey) {
      try {
        const neatlogsModule = await import('neatlogs');
        const ClientClass = (neatlogsModule as any).Client || (neatlogsModule as any).default?.Client;
        if (ClientClass) {
          this.client = new ClientClass({ apiKey: this.apiKey });
        }
      } catch (err: any) {
        console.warn(`[Neatlogs] Remote client init notice: ${err.message}. Operating in hybrid mode.`);
      }
    }
  }

  /**
   * Records an error span to the local telemetry queue (used by the instrumented demo server).
   */
  async recordLocalFailureSpan(span: FailureSpan): Promise<void> {
    let existing: FailureSpan[] = [];
    if (fs.existsSync(this.localTelemetryQueueFile)) {
      try {
        existing = JSON.parse(fs.readFileSync(this.localTelemetryQueueFile, 'utf-8'));
      } catch {
        existing = [];
      }
    }
    existing.push(span);
    fs.writeFileSync(this.localTelemetryQueueFile, JSON.stringify(existing, null, 2), 'utf-8');
  }

  /**
   * Retrieves the latest unhandled failure span.
   */
  async getLatestFailureSpan(): Promise<FailureSpan | null> {
    // 1. Try remote Neatlogs if client is available
    if (this.client && typeof this.client.getSpans === 'function') {
      try {
        const spans = await this.client.getSpans({
          status: 'error',
          since: this.lastPolledTimestamp,
          limit: 1
        });
        if (spans && spans.length > 0) {
          const rawSpan = spans[0];
          if (!this.seenTraceIds.has(rawSpan.traceId)) {
            this.seenTraceIds.add(rawSpan.traceId);
            this.lastPolledTimestamp = Date.now();
            return TraceInterceptor.extractFailureContext({
              traceId: rawSpan.traceId,
              spanId: rawSpan.spanId || rawSpan.id,
              name: rawSpan.name,
              errorMessage: rawSpan.error || rawSpan.message,
              errorStack: rawSpan.stack || rawSpan.errorStack,
              timestamp: rawSpan.timestamp || Date.now(),
              rawAttributes: rawSpan
            });
          }
        }
      } catch (err: any) {
        console.warn(`[Neatlogs] Remote span query failed: ${err.message}. Falling back to local queue.`);
      }
    }

    // 2. Inspect local telemetry buffer from the instrumented app
    if (fs.existsSync(this.localTelemetryQueueFile)) {
      try {
        const fileContent = fs.readFileSync(this.localTelemetryQueueFile, 'utf-8');
        const spans: FailureSpan[] = JSON.parse(fileContent);
        for (let i = spans.length - 1; i >= 0; i--) {
          const s = spans[i];
          if (!this.seenTraceIds.has(s.traceId)) {
            this.seenTraceIds.add(s.traceId);
            this.lastPolledTimestamp = Date.now();
            return TraceInterceptor.extractFailureContext(s);
          }
        }
      } catch (err: any) {
        throw new TraceFetchFailed(`Failed to read local telemetry queue: ${err.message}`);
      }
    }

    return null;
  }

  /**
   * Runs comparative evaluation between the failure baseline trace and the post-fix trace.
   */
  async runComparativeEval(baselineTraceId: string, healedTraceId: string): Promise<ComparativeEvalResult> {
    const baselineUrl = this.traceUrlTemplate.replace('${id}', baselineTraceId);
    const healedUrl = this.traceUrlTemplate.replace('${id}', healedTraceId);

    // If remote client is available, attempt to get real metrics
    if (this.client && typeof this.client.getTrace === 'function') {
      try {
        const baseline = await this.client.getTrace(baselineTraceId);
        const healed = await this.client.getTrace(healedTraceId);

        if (baseline?.errorCount !== undefined && healed?.errorCount !== undefined) {
          return {
            mode: 'PROGRAMMATIC_EVAL',
            baselineTraceId,
            healedTraceId,
            baselineTraceUrl: baselineUrl,
            healedTraceUrl: healedUrl,
            baselineErrors: baseline.errorCount,
            healedErrors: healed.errorCount,
            deltaErrors: baseline.errorCount - healed.errorCount,
            durationMs: healed.duration,
            tokenCostUSD: healed.tokenCost,
            status: healed.errorCount === 0 ? 'VERIFIED_PASS' : 'REGRESSION_DETECTED'
          };
        }
      } catch (err: any) {
        console.warn(`[Neatlogs] Programmatic eval failed: ${err.message}`);
      }
    }

    // Check local recorded traces
    if (fs.existsSync(this.localTelemetryQueueFile)) {
      try {
        const spans: FailureSpan[] = JSON.parse(
          fs.readFileSync(this.localTelemetryQueueFile, 'utf-8')
        );
        const baselineSpan = spans.find((s) => s.traceId === baselineTraceId);
        const healedSpan = spans.find((s) => s.traceId === healedTraceId);

        if (baselineSpan && healedSpan) {
          const baselineErrors = 1;
          const healedErrors = healedSpan.errorMessage ? 1 : 0;
          return {
            mode: 'PROGRAMMATIC_EVAL',
            baselineTraceId,
            healedTraceId,
            baselineTraceUrl: baselineUrl,
            healedTraceUrl: healedUrl,
            baselineErrors,
            healedErrors,
            deltaErrors: baselineErrors - healedErrors,
            status: healedErrors === 0 ? 'VERIFIED_PASS' : 'REGRESSION_DETECTED',
            note: 'Verified from local instrumented telemetry trace log.'
          };
        }
      } catch {
        // Fallback below
      }
    }

    // Honest fallback: output dashboard URLs for camera verification
    return {
      mode: 'DASHBOARD_SIDE_BY_SIDE',
      baselineTraceId,
      healedTraceId,
      baselineTraceUrl: baselineUrl,
      healedTraceUrl: healedUrl,
      status: 'MANUAL_VERIFICATION_REQUIRED',
      note: 'Read error delta and duration directly from neatlogs dashboard.'
    };
  }

  clearLocalQueue(): void {
    if (fs.existsSync(this.localTelemetryQueueFile)) {
      fs.unlinkSync(this.localTelemetryQueueFile);
    }
    this.seenTraceIds.clear();
  }
}

/**
 * SutureLoop Unit Economics & Financial Calculator
 * Feeds into cfo.ai Financial Model in docs/BUSINESS-PLAN.md
 *
 * Rules:
 * - No fictitious numbers.
 * - Inputs are derived from measured token consumption and industry standard engineering rates.
 */

export interface EconomicMetrics {
  measuredTokenCostUSD: number;
  mttrHoursSaved: number;
  hourlyEngineerRateUSD: number;
  grossSavingsUSD: number;
  netSavingsUSD: number;
  grossMarginPercent: number;
}

export interface BusinessPlanMetrics {
  perIncident: EconomicMetrics;
  monthlyProjections: {
    incidentsPerMonth: number;
    agentRunningCostUSD: number;
    engineeringTimeSavedUSD: number;
    netMonthlySavingsUSD: number;
    grossMarginPercent: number;
  };
  subscriptionTiers: {
    tierName: string;
    incidentsIncluded: number;
    monthlyPriceUSD: number;
    estimatedGrossMarginPercent: number;
  }[];
}

export function calculateIncidentEconomics(params: {
  measuredTokenCostUSD: number;
  mttrMinutesSaved?: number;
  hourlyEngineerRateUSD?: number;
}): EconomicMetrics {
  const mttrHours = (params.mttrMinutesSaved ?? 45) / 60;
  const rate = params.hourlyEngineerRateUSD ?? 125;
  const grossSavings = mttrHours * rate;
  const netSavings = grossSavings - params.measuredTokenCostUSD;
  const margin =
    grossSavings > 0
      ? ((grossSavings - params.measuredTokenCostUSD) / grossSavings) * 100
      : 0;

  return {
    measuredTokenCostUSD: Number(params.measuredTokenCostUSD.toFixed(4)),
    mttrHoursSaved: Number(mttrHours.toFixed(2)),
    hourlyEngineerRateUSD: rate,
    grossSavingsUSD: Number(grossSavings.toFixed(2)),
    netSavingsUSD: Number(netSavings.toFixed(2)),
    grossMarginPercent: Math.round(margin * 10) / 10
  };
}

export function generateBusinessModel(
  measuredCostPerFix: number
): BusinessPlanMetrics {
  const perIncident = calculateIncidentEconomics({
    measuredTokenCostUSD: measuredCostPerFix,
    mttrMinutesSaved: 45,
    hourlyEngineerRateUSD: 125
  });

  const monthly50 = 50;
  const cost50 = measuredCostPerFix * monthly50;
  const savings50 = perIncident.grossSavingsUSD * monthly50;

  return {
    perIncident,
    monthlyProjections: {
      incidentsPerMonth: monthly50,
      agentRunningCostUSD: Number(cost50.toFixed(2)),
      engineeringTimeSavedUSD: Number(savings50.toFixed(2)),
      netMonthlySavingsUSD: Number((savings50 - cost50).toFixed(2)),
      grossMarginPercent: perIncident.grossMarginPercent
    },
    subscriptionTiers: [
      {
        tierName: 'Starter (15 fixes/mo)',
        incidentsIncluded: 15,
        monthlyPriceUSD: 79,
        estimatedGrossMarginPercent: Number(
          (((79 - 15 * measuredCostPerFix) / 79) * 100).toFixed(1)
        )
      },
      {
        tierName: 'Growth (50 fixes/mo)',
        incidentsIncluded: 50,
        monthlyPriceUSD: 199,
        estimatedGrossMarginPercent: Number(
          (((199 - 50 * measuredCostPerFix) / 199) * 100).toFixed(1)
        )
      },
      {
        tierName: 'Scale (200 fixes/mo)',
        incidentsIncluded: 200,
        monthlyPriceUSD: 599,
        estimatedGrossMarginPercent: Number(
          (((599 - 200 * measuredCostPerFix) / 599) * 100).toFixed(1)
        )
      }
    ]
  };
}

