      const healedData = await healedRes.json();
      console.log(`  ✓ Service responded with HTTP ${healedRes.status}:`, JSON.stringify(healedData));
      console.log(`\n🎉 End-to-End Demo Successfully Completed!`);
    } finally {
      healedServerProc.kill();
    }
  } finally {
    serverProc.kill();
  }
}

