/* MOTIONS & SPOTLIGHT */
#cursorGlow{
  position:fixed;top:0;left:0;width:560px;height:560px;border-radius:50%;
  pointer-events:none;z-index:0;
  background:radial-gradient(circle,rgba(110,242,192,.08),transparent 70%);
  transform:translate(-50%,-50%);
  transition:opacity .3s ease;
  opacity:0;
}
body:hover #cursorGlow{opacity:1}

@keyframes heroIn{
  from{opacity:0;transform:translateY(18px)}
  to{opacity:1;transform:none}
}
.hero > div > *{animation:heroIn .7s cubic-bezier(.16,1,.3,1) both}
.hero .badge{animation-delay:.05s}
.hero h1{animation-delay:.15s}
.hero .lead{animation-delay:.25s}
.hero .cta{animation-delay:.35s}
.hero .assure{animation-delay:.45s}

.card, .stat{
  transition:transform .22s cubic-bezier(.2,.8,.4,1),border-color .3s,box-shadow .3s;
  transform-style:preserve-3d;
  will-change:transform;
}
.card:hover{
  box-shadow:0 24px 50px -15px rgba(0,0,0,.8),0 0 25px rgba(110,242,192,.1);
}
.stat:hover{
  background:rgba(18,24,27,.9);
  box-shadow:inset 0 0 20px rgba(110,242,192,.04);
}

#sutureToast{
  position:fixed;bottom:28px;right:28px;z-index:100;
  background:rgba(14,19,21,.94);backdrop-filter:blur(16px);
  border:1px solid var(--ok);border-radius:14px;padding:14px 18px;
  font:500 13px var(--mono);color:var(--text);
  box-shadow:0 20px 50px rgba(0,0,0,.85),0 0 20px rgba(110,242,192,.25);
  display:flex;align-items:center;gap:12px;
  transform:translateY(100px);opacity:0;transition:transform .4s cubic-bezier(.16,1,.3,1),opacity .4s;
  pointer-events:none;max-width:440px;
