  /* ---------- SOUND FX SYNTHESIZER (WEB AUDIO API) ---------- */
  let soundEnabled = true;
  let audioCtx = null;
  function getAudioContext(){
    if(!audioCtx && (window.AudioContext || window.webkitAudioContext)){
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if(audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
    return audioCtx;
  }
  function playAudio(type){
    if(!soundEnabled) return;
    try {
      const ctx = getAudioContext();
      if(!ctx) return;
      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      if(type === 'click'){
        osc.frequency.setValueAtTime(800, now);
        osc.frequency.exponentialRampToValueAtTime(1200, now + 0.03);
        gain.gain.setValueAtTime(0.04, now);
        gain.gain.linearRampToValueAtTime(0.001, now + 0.03);
        osc.start(now);
        osc.stop(now + 0.03);
      } else if(type === 'stage'){
        osc.frequency.setValueAtTime(440, now);
        osc.frequency.exponentialRampToValueAtTime(880, now + 0.07);
        gain.gain.setValueAtTime(0.06, now);
        gain.gain.linearRampToValueAtTime(0.001, now + 0.07);
        osc.start(now);
        osc.stop(now + 0.07);
      } else if(type === 'crash'){
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(140, now);
        osc.frequency.exponentialRampToValueAtTime(70, now + 0.18);
        gain.gain.setValueAtTime(0.08, now);
        gain.gain.linearRampToValueAtTime(0.001, now + 0.18);
        osc.start(now);
        osc.stop(now + 0.18);
      } else if(type === 'healed'){
        // Dual harmonic chime
        [523.25, 783.99, 1046.50].forEach((freq, idx) => {
          const chordOsc = ctx.createOscillator();
          const chordGain = ctx.createGain();
          chordOsc.type = 'sine';
          chordOsc.connect(chordGain);
          chordGain.connect(ctx.destination);
          chordOsc.frequency.setValueAtTime(freq, now + idx * 0.05);
          chordGain.gain.setValueAtTime(0.05, now + idx * 0.05);
          chordGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.45);
          chordOsc.start(now + idx * 0.05);
          chordOsc.stop(now + 0.45);
        });
      }
    } catch(e) {}
  }

  const soundBtn = $('#soundToggle');
  if(soundBtn){
    soundBtn.addEventListener('click', ()=>{
      soundEnabled = !soundEnabled;
      $('#soundIcon').textContent = soundEnabled ? '🔊' : '🔇';
      soundBtn.innerHTML = `<span id="soundIcon">${soundEnabled ? '🔊' : '🔇'}</span> FX: ${soundEnabled ? 'ON' : 'MUTED'}`;
      if(soundEnabled) playAudio('click');
    });
  }

  /* ---------- FLOATING TOAST ---------- */
  const toast = $('#sutureToast');
  let toastTimer = null;
  function showToast(msg, dur = 3800){
    if(!toast) return;
    toast.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#6ef2c0" stroke-width="2.2" stroke-linecap="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg><span>${msg}</span>`;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>toast.classList.remove('show'), dur);
  }

  /* ---------- HERO SIMULATE BUTTON ---------- */
  const heroSimBtn = $('#btnSimulateHero');
  if(heroSimBtn){
    heroSimBtn.addEventListener('click', ()=>{
      playAudio('crash');
      document.body.classList.add('screen-flashing');
      setTimeout(()=>document.body.classList.remove('screen-flashing'), 1200);

      showToast('🚨 Intercepted unhandled TypeError in payments-svc! Closing the loop...');
      const target = $('#theater');
      if(target) target.scrollIntoView({ behavior: 'smooth' });

      setTimeout(()=>{
        play();
      }, 400);
    });
  }

  /* ---------- CURSOR SPOTLIGHT TRACKER ---------- */
  const glow = $('#cursorGlow');
  if(glow && !reduce){
    let mouseX = window.innerWidth / 2, mouseY = window.innerHeight / 2;
    window.addEventListener('mousemove', e=>{
      mouseX = e.clientX; mouseY = e.clientY;
      glow.style.left = mouseX + 'px';
      glow.style.top = mouseY + 'px';
    });
  }

  /* ---------- 3D CARD PERSPECTIVE TILT ---------- */
  const tiltCards = document.querySelectorAll('.card, .stat');
  if(!reduce){
    tiltCards.forEach(card=>{
      card.addEventListener('mousemove', e=>{
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left - rect.width / 2;
        const y = e.clientY - rect.top - rect.height / 2;
        const rotX = -(y / (rect.height / 2)) * 6.5;
        const rotY = (x / (rect.width / 2)) * 6.5;
        card.style.transform = `perspective(800px) rotateX(${rotX.toFixed(2)}deg) rotateY(${rotY.toFixed(2)}deg) translateY(-4px)`;
      });
      card.addEventListener('mouseleave', ()=>{
        card.style.transform = 'perspective(800px) rotateX(0deg) rotateY(0deg) translateY(0px)';
      });
    });
  }

  /* initial idle render */
  renderStage(0);reveal(0);
  setPill('','Awaiting crash');
  clock.innerHTML='0.00<small>s</small>';

  const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const box=$('#theaterBox');
  let started=false;
  if('IntersectionObserver' in window){
    new IntersectionObserver((es,ob)=>{
      es.forEach(e=>{
        if(e.isIntersecting&&!started){
          started=true;ob.disconnect();
          reduceMotion?finish():play();
        }
      });
    },{threshold:.35}).observe(box);
  } else { started=true; reduceMotion?finish():play(); }

  /* ---------- COUNT-UP ---------- */
  const counters=[...document.querySelectorAll('[data-count]')];
  if('IntersectionObserver' in window&&!reduceMotion){
    const io=new IntersectionObserver((es)=>{
      es.forEach(e=>{
        if(!e.isIntersecting)return;
        io.unobserve(e.target);
        const el=e.target,to=parseFloat(el.dataset.count),d=parseInt(el.dataset.dec||0);
        const t0=performance.now(),dur=1200;
        (function tick(n){
          const k=Math.min(1,(n-t0)/dur),v=to*(1-Math.pow(1-k,3));
          el.textContent=v.toFixed(d);
          if(k<1)requestAnimationFrame(tick);
        })(t0);
      });
    },{threshold:.6});
    counters.forEach(c=>{c.textContent=(0).toFixed(parseInt(c.dataset.dec||0));io.observe(c);});
  }
})();
</script>

